52	    @Test
53	    void concurrentOverlappingCertificatesAtMostOneSucceeds() throws Exception {
54	        int threads = 8;
55	        ExecutorService pool = Executors.newFixedThreadPool(threads);
56	        CountDownLatch start = new CountDownLatch(1);
57	        List<Future<Integer>> results = new ArrayList<>();
58	        for (int i = 0; i < threads; i++) {
59	            int index = i;
60	            results.add(pool.submit(() -> {
61	                start.await();
62	                ResultActions action = mvc.perform(post("/api/certificates")
63	                        .contentType(MediaType.APPLICATION_JSON)
64	                        .content("""
65	                                {"instrumentId":"INS-C","validFrom":"2026-01-01T00:00:00Z",
66	                                 "validTo":"2027-01-01T00:00:00Z","a":"1","b":"0"}"""));
67	                return action.andReturn().getResponse().getStatus();
68	            }));
69	        }
70	        start.countDown();
71	        AtomicInteger created = new AtomicInteger();
72	        AtomicInteger conflicts = new AtomicInteger();
73	        for (Future<Integer> future : results) {
74	            int status = future.get(30, TimeUnit.SECONDS);
75	            if (status == 201) {
76	                created.incrementAndGet();
77	            } else if (status == 409) {
78	                conflicts.incrementAndGet();
79	            }
80	        }
81	        pool.shutdown();
82	        assertEquals(1, created.get(), "重叠证书并发创建必须恰好一张成功");
83	        assertEquals(threads - 1, conflicts.get(), "其余必须为 409 冲突");
84	    }
