102	                            {"measurementKey":"M-%d","instrumentId":"INS-R%d",
103	                             "measuredAt":"2026-06-01T00:00:00Z","reading":"1",
104	                             "lowerLimit":"0","upperLimit":"9","submittedBy":"alice"}""".formatted(r, r)))
105	                    .andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().isCreated());
106	
107	            ExecutorService pool = Executors.newFixedThreadPool(2);
108	            CountDownLatch start = new CountDownLatch(1);
109	            Future<Integer> revokeFuture = pool.submit(() -> {
110	                start.await();
111	                return mvc.perform(post("/api/certificates/{id}/revoke", certId))
112	                        .andReturn().getResponse().getStatus();
